function delayedResult(ms, value, signal) {
  return new Promise((resolve, reject) => {
    let timer;
    const onAbort = () => {
      clearTimeout(timer);
      const error = new Error("Superseded");
      error.name = "AbortError";
      reject(error);
    };
    if (signal.aborted) return onAbort();
    signal.addEventListener("abort", onAbort, { once: true });
    timer = setTimeout(() => resolve(value), ms);
  });
}

let latestRequest = 0;
let activeController;
let shown = null;

async function search(query, ms) {
  const requestId = ++latestRequest;
  activeController?.abort();
  const controller = new AbortController();
  activeController = controller;

  try {
    const result = await delayedResult(ms, query.toUpperCase(), controller.signal);
    if (requestId === latestRequest) shown = result;
  } catch (error) {
    if (error.name !== "AbortError" && requestId === latestRequest) throw error;
  }
}

const oldSearch = search("c", 30);
const newSearch = search("cat", 5);
await Promise.all([oldSearch, newSearch]);
console.log(shown);

