let loading = false;
let errorMessage = null;

async function submit(save) {
  loading = true;
  errorMessage = null;
  try {
    return await save();
  } catch (error) {
    errorMessage = error.message;
    throw error;
  } finally {
    loading = false;
  }
}

await submit(() => Promise.reject(new Error("offline"))).catch(() => {});
console.log(loading, errorMessage);

sections.content:
**State ownership.** `finally` solves missing cleanup for one operation. A token or count solves competing cleanup across several operations. They address different failure modes and may both be required.

```mermaid
stateDiagram-v2
  [*] --> Idle
  Idle --> Loading: operation starts
  Loading --> Success: await fulfills
  Loading --> Error: await rejects
  Success --> Idle: finally
  Error --> Idle: finally
  Loading --> Loading: newer operation replaces owner
```

**Runnable example.** Cleanup runs for the rejected operation without converting it into silent success.

```javascript
let loading = false;
let errorMessage = null;

async function submit(save) {
  loading = true;
  errorMessage = null;
  try {
    return await save();
  } catch (error) {
    errorMessage = error.message;
    throw error;
  } finally {
    loading = false;
  }
}

try { await submit(() => Promise.reject(new Error("offline"))); } catch {}
console.log(loading, errorMessage); // false offline
```

**Boundary.** Some interfaces should keep previous data visible while a refresh is pending instead of replacing the whole view with a spinner. Loading state should describe the user experience, not merely mirror the existence of any Promise.
